function migrateAuthSessionToBrowser(){
  for(let index=0;index<sessionStorage.length;index++){
    const key=sessionStorage.key(index);
    if(!key||!/^sb-/.test(key)||!key.includes('auth-token')||localStorage.getItem(key))continue;
    const existing=sessionStorage.getItem(key);
    if(existing)localStorage.setItem(key,existing);
  }
}
function clearSupabaseAuthStorage(){
  for(const storage of [localStorage,sessionStorage]){
    for(let index=storage.length-1;index>=0;index--){const key=storage.key(index);if(key&&(key===SUPABASE_AUTH_KEY||(/^sb-/.test(key)&&key.includes('auth-token'))))storage.removeItem(key)}
  }
}
