tr.pl.goldGram='ZŁOTO / GRAM I UNCJA';tr.en.goldGram='GOLD / GRAM & OUNCE';

function assetCatalog(){const catalog={...assets,...fallbackCryptoAssets,...state.walletAssets};state.coins.forEach(c=>{if(c.id==='bitcoin')return;catalog[`cg:${c.id}`]={pl:c.name,en:c.name,symbol:c.symbol.toUpperCase(),tv:`BINANCE:${c.symbol.toUpperCase()}USDT`,unit:c.symbol.toUpperCase(),icon:c.image,type:'crypto',coin:c}});return catalog}
function findAsset(id){return assetCatalog()[id]}
const defaultWatchlist=['btc','gbp','gold','silver','sp500','spacex'];
function watchKey(){return state.user?`vestorWatchlist:user:${state.user.id}`:'vestorWatchlist'}
function parsedWatchlist(key){try{const value=JSON.parse(localStorage.getItem(key)||'null');return Array.isArray(value)?value.filter(id=>typeof id==='string').slice(0,100):null}catch{return null}}
function legacyWatchKeys(){
  if(!state.user)return ['vestorWatchlist'];
  const name=state.user.name.toLowerCase(),emailName=state.user.email.split('@')[0].toLowerCase(),keys=[`vestorWatchlist:${name}`,`vestorWatchlist:${emailName}`];
  if(state.user.email==='calabraaa@gmail.com')keys.unshift('vestorWatchlist:martin');
  keys.push('vestorWatchlist');
  return [...new Set(keys)];
}
function getWatchlist(){
  if(!state.user)return defaultWatchlist;
  const current=parsedWatchlist(watchKey());
  if(current)return current;
  const recovered=legacyWatchKeys().map(key=>parsedWatchlist(key)).filter(Boolean).sort((a,b)=>b.length-a.length)[0];
  const list=recovered||defaultWatchlist;
  localStorage.setItem(watchKey(),JSON.stringify(list));
  return list;
}
function saveWatchlist(list){const saved=list.slice(0,100);localStorage.setItem(watchKey(),JSON.stringify(saved));if(state.user?.email==='calabraaa@gmail.com')localStorage.setItem('vestorWatchlist:martin',JSON.stringify(saved))}

function cleanProfileText(value,fallback='Investor'){const text=String(value||'').replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,80);return text||fallback}
function appUser(user){if(!user)return null;const email=String(user.email||'').trim().toLowerCase();return {id:user.id,email,name:cleanProfileText(user.user_metadata?.display_name,email.split('@')[0]||'Investor'),created:user.created_at}}
async function inviteCode(){const {data,error}=await authClient.rpc('get_current_invite_code');if(error)return null;return data}
async function register(email,password,invite){const normalized=email.trim().toLowerCase();if(!invite.trim())throw Error('inviteRequired');const {data,error}=await authClient.auth.signUp({email:normalized,password,options:{emailRedirectTo:`${location.origin}${location.pathname}`,data:{display_name:cleanProfileText(normalized.split('@')[0]),invitation_code:invite.replace(/\s/g,'')}}});if(error)throw error;return data}
async function authenticate(email,password){const {data,error}=await authClient.auth.signInWithPassword({email:email.trim().toLowerCase(),password});if(error)throw error;return appUser(data.user)}
async function securityLog(kind,details={}){
  try{await authClient.rpc('log_security_event',{kind,event_details:details})}
  catch(error){console.warn('Security event could not be recorded.',error)}
}
function portfolioKey(){return `vestorPortfolio:${state.user?.id||'signed-out'}`}
function portfolioPrivacyKey(){return state.user?`vestorPortfolioPrivacy:${state.user.id}`:'vestorPortfolioPrivacy'}
function applyPortfolioPrivacy(){const hidden=Boolean(state.portfolioPrivate),app=$('#app'),button=$('#portfolioPrivacyButton');app?.classList.toggle('portfolio-private',hidden);if(!button)return;const label=t(hidden?'showPortfolio':'hidePortfolio');button.textContent=hidden?'⊘':'◉';button.title=label;button.setAttribute('aria-label',label);button.setAttribute('aria-pressed',String(hidden))}
function togglePortfolioPrivacy(){state.portfolioPrivate=!state.portfolioPrivate;localStorage.setItem(portfolioPrivacyKey(),state.portfolioPrivate?'1':'0');applyPortfolioPrivacy()}
function legacyPortfolioKeys(){return state.user?[`vestorPortfolio:${state.user.name.toLowerCase()}`,`vestorPortfolioBackup:${state.user.email.toLowerCase()}`]:[]}
function parsePortfolio(value){try{const rows=JSON.parse(value||'[]');return Array.isArray(rows)?rows:[]}catch{return []}}
function normalizePortfolio(rows){return rows.map((row,index)=>{if(row.assetMeta&&row.asset)state.walletAssets[row.asset]={...row.assetMeta,walletPrice:Number(row.assetMeta.walletPrice)||0};return {...row,id:row.id||`${row.asset||'asset'}-${row.added||row.purchasedAt||Date.now()}-${index}`}})}
function legacyPortfolio(){const primary=parsePortfolio(localStorage.getItem(portfolioKey()));if(primary.length)return normalizePortfolio(primary);for(const key of legacyPortfolioKeys()){const rows=parsePortfolio(localStorage.getItem(key));if(rows.length)return normalizePortfolio(rows)}return []}
function getPortfolio(){return state.portfolio}
function persistPortfolioLocal(rows,updatedAt=Date.now()){const normalized=normalizePortfolio(rows);localStorage.setItem(portfolioKey(),JSON.stringify(normalized));for(const key of legacyPortfolioKeys())localStorage.setItem(key,JSON.stringify(normalized));localStorage.setItem(`${portfolioKey()}:updatedAt`,String(updatedAt));return normalized}
let portfolioWrite=Promise.resolve();
async function persistPortfolioDatabase(rows){if(!state.user)return;const payload=normalizePortfolio(rows),ids=new Set(payload.map(row=>String(row.id))),records=payload.map(row=>({user_id:state.user.id,client_id:String(row.id),payload:row,updated_at:new Date().toISOString()}));if(records.length){const {error}=await authClient.from('portfolio_positions').upsert(records,{onConflict:'user_id,client_id'});if(error)throw error}const {data:existing,error:readError}=await authClient.from('portfolio_positions').select('client_id');if(readError)throw readError;const stale=(existing||[]).map(row=>row.client_id).filter(id=>!ids.has(id));if(stale.length){const {error}=await authClient.from('portfolio_positions').delete().in('client_id',stale);if(error)throw error}}
function clearLegacyPortfolio(){[portfolioKey(),`${portfolioKey()}:updatedAt`,...legacyPortfolioKeys()].forEach(key=>localStorage.removeItem(key))}
function savePortfolio(rows){const normalized=normalizePortfolio(rows);state.portfolio=normalized;if(state.portfolioStorage==='database'){portfolioWrite=portfolioWrite.then(()=>persistPortfolioDatabase(normalized)).catch(error=>{console.error('Portfolio sync failed',error);securityLog('portfolio_sync_failed',{message:String(error?.message||'unknown').slice(0,160)});state.portfolioStorage='local-fallback';persistPortfolioLocal(normalized)})}else persistPortfolioLocal(normalized);return normalized}
async function syncPortfolioFromCloud(authUser){const metadataRaw=authUser?.user_metadata?.vestor_portfolio,metadata=Array.isArray(metadataRaw)?metadataRaw:Array.isArray(metadataRaw?.items)?metadataRaw.items:[],legacy=legacyPortfolio(),migrationSource=normalizePortfolio(legacy.length?legacy:metadata);const {data,error}=await authClient.from('portfolio_positions').select('client_id,payload').order('created_at');if(error){state.portfolio=migrationSource;state.portfolioStorage='local-fallback';if(migrationSource.length)persistPortfolioLocal(migrationSource);console.warn('Run the current supabase-setup.sql migration to enable protected portfolio storage.',error);return}const remote=normalizePortfolio((data||[]).map(row=>({...row.payload,id:row.client_id})));state.portfolioStorage='database';if(remote.length){state.portfolio=remote;clearLegacyPortfolio();return}state.portfolio=migrationSource;if(migrationSource.length){await persistPortfolioDatabase(migrationSource);const {data:check,error:checkError}=await authClient.from('portfolio_positions').select('client_id');if(!checkError&&check?.length===migrationSource.length){clearLegacyPortfolio();await authClient.auth.updateUser({data:{vestor_portfolio:null}});securityLog('portfolio_migrated',{positions:migrationSource.length})}}}

function applyLanguage(){document.documentElement.lang=state.lang;$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));$('#languageButton').textContent=state.lang==='pl'?'EN':'PL';$('#loginLanguageButton').textContent=state.lang==='pl'?'EN':'PL';$('#togglePassword').setAttribute('aria-label',$('#loginPassword').type==='password'?t('showPassword'):t('hidePassword'));$('#authSubmitText').textContent=state.mode==='login'?t('loginAction'):t('registerAction');$('#loginName').placeholder=state.lang==='pl'?'twoj@email.com':'your@email.com';$('#coinSearch').placeholder=state.lang==='pl'?'Szukaj aktywa…':'Search assets…';$('#watchSearch').placeholder=t('watchSearch');$('#greeting').textContent=state.user?`${t('hello')}, ${state.user.name}.`:`${t('hello')}.`;$('#todayLabel').textContent=new Intl.DateTimeFormat(state.lang==='pl'?'pl-PL':'en-GB',{weekday:'long',day:'numeric',month:'long'}).format(new Date()).toUpperCase();renderTabs();renderWatchlist();renderPortfolio();renderCoins();renderWatchingCards();renderWatchEditor();renderCryptoEtfs();updateAssetSelect();renderConnectedWallets();renderSettings();applyPortfolioPrivacy();if(!$('#marketStatusPage').hidden)loadMarketStatus();if(!$('#vestorIndicatorPage').hidden)loadVestorIndicator()}
const systemTheme=matchMedia('(prefers-color-scheme: dark)');
function effectiveTheme(){return state.theme==='auto'?(systemTheme.matches?'dark':'light'):state.theme}
function applyTheme(){const active=effectiveTheme();document.documentElement.dataset.theme=active;$('#themeButton').textContent=state.theme==='auto'?'◐':state.theme==='dark'?'☾':'☀';$('#themeButton').title=state.theme==='auto'?t('themeAuto'):state.theme==='dark'?t('themeDark'):t('themeLight');$('#themeButton').setAttribute('aria-label',$('#themeButton').title);if(state.user)renderTradingView(activeOverviewAsset||'btc');if(activeCoin&&!$('#coinDetailPage').hidden)renderActiveCoinChart()}
let authGeneration=0,logoutInProgress=false,explicitLoginInProgress=false;
function showLoginScreen(){state.user=null;state.role='user';$('#app').hidden=true;$('#loginView').hidden=false}
window.addEventListener('storage',event=>{if(event.key===SUPABASE_AUTH_KEY&&!event.newValue&&!logoutInProgress){authGeneration++;state.portfolio=[];state.walletAssets={};showLoginScreen()}});
async function showApp(runId=authGeneration){
  try{
    const {data,error}=await authClient.auth.getSession();
    if(error)throw error;
    if(runId!==authGeneration||logoutInProgress)return;
    const authUser=data.session?.user;
    if(!authUser){showLoginScreen();return}
    state.user=appUser(authUser);
    let role='user';
    try{const result=await authClient.rpc('get_my_role');if(!result.error)role=result.data||'user'}catch(error){console.warn('Role lookup failed; using the standard user role.',error)}
    if(runId!==authGeneration||logoutInProgress)return;
    state.role=role;
    state.portfolioPrivate=localStorage.getItem(portfolioPrivacyKey())==='1';
    try{await syncPortfolioFromCloud(authUser)}catch(error){console.error('Portfolio startup sync failed.',error);state.portfolio=legacyPortfolio();state.portfolioStorage='local-fallback'}
    if(runId!==authGeneration||logoutInProgress)return;
    restoreBitcoinQuote();
    restoreQuoteCache();
    $('#loginError').textContent='';
    $('#loginView').hidden=true;
    $('#app').hidden=false;
    $('#profileName').textContent=state.user.name;
    $('#profileInitials').textContent=state.user.name.slice(0,2).toUpperCase();
    applyLanguage();
    loadMarketData();
    loadMarketQuotes();
    loadCoins();
    loadExchangeSymbols();
    renderSettings();
  }catch(error){
    if(runId!==authGeneration||logoutInProgress)return;
    console.error('Dashboard startup failed.',error);
    $('#loginError').classList.remove('success');
    $('#loginError').textContent=state.lang==='pl'?'Zalogowano, ale panel nie mógł się uruchomić. Odśwież stronę.':'Signed in, but the dashboard could not start. Refresh the page.';
  }
}

