$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const email=$('#loginName').value.trim(),pass=$('#loginPassword').value,err=$('#loginError');err.textContent='';explicitLoginInProgress=true;try{if(!email.includes('@'))throw Error('email');if(state.mode==='register'){if(pass.length<8)throw Error('short');if(pass!==$('#repeatPassword').value)throw Error('mismatch');await register(email,pass,$('#inviteCodeInput').value);state.mode='login';$('[data-auth="login"]').click();err.classList.add('success');err.textContent=t('confirmYourEmail');return}await authenticate(email,pass);const runId=++authGeneration;await showApp(runId)}catch(ex){err.classList.remove('success');const message=(ex.message||'').toLowerCase();err.textContent=ex.message==='email'?t('invalidEmail'):ex.message==='short'?t('shortPassword'):ex.message==='mismatch'?t('passwordMismatch'):ex.message==='inviteRequired'?t('inviteRequired'):message.includes('invitation')||message.includes('database error')?t('inviteInvalid'):message.includes('email not confirmed')?t('confirmYourEmail'):t('badLogin')}finally{explicitLoginInProgress=false}});
