async function logout(){
  if(logoutInProgress)return;
  authGeneration++;
  logoutInProgress=true;
  void securityLog('sign_out');
  state.portfolio=[];
  state.walletAssets={};
  showLoginScreen();
  $('#loginPassword').value='';
  $('#profileMenu').classList.remove('open');
  try{
    const result=await Promise.race([authClient.auth.signOut(),new Promise(resolve=>setTimeout(()=>resolve({error:new Error('Sign-out timeout')}),8000))]);
    if(result?.error)console.warn('Supabase sign-out response:',result.error);
  }catch(error){
    console.warn('Browser sign-out cleanup completed after an auth error.',error);
  }finally{
    clearSupabaseAuthStorage();
    logoutInProgress=false;
  }
}
