function fmt(value,digits=2){return new Intl.NumberFormat(state.lang==='pl'?'pl-PL':'en-GB',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value)}
function usd(value,digits=2){return state.usdPln?`$${fmt(value/state.usdPln,digits)}`:'$—'}
function assetUsd(id){if(id==='usd')return 1;if(id==='pln')return state.usdPln?1/state.usdPln:0;const a=findAsset(id);if(a?.coin)return a.coin.current_price;if(a?.walletPrice)return Number(a.walletPrice);const matching=state.coins.find(coin=>a?.symbol&&coin.symbol.toUpperCase()===a.symbol.toUpperCase());if(matching)return Number(matching.current_price)||0;if(['cg:tether','cg:usd-coin'].includes(id))return 1;return state.pricesUSD[id]||((state.prices[id]&&state.usdPln)?state.prices[id]/state.usdPln:0)}
function assetPln(id){const u=assetUsd(id);return state.prices[id]||(u&&state.usdPln?u*state.usdPln:0)}
function dualPrice(id,digits=2){const u=assetUsd(id),p=assetPln(id);if(id==='usd')return state.usdPln?`${fmt(state.usdPln,4)} zł`:'—';if(id==='gbp')return p?`${fmt(p,4)} zł`:'—';if(id==='spacex')return state.lang==='pl'?'Spółka prywatna':'Private company';if(!u)return '—';if(['sp500','wig','wig20'].includes(id))return `${fmt(u)} ${state.lang==='pl'?'pkt':'pts'}`;if(id==='gold'){const ounceUsd=u*31.1034768,ouncePln=p*31.1034768,main=`$${fmt(u)}/g · $${fmt(ounceUsd)}/oz`;return state.lang==='pl'?`${main}<small>${fmt(p)} zł/g · ${fmt(ouncePln)} zł/oz</small>`:main}if(id==='oil'){const main=`$${fmt(u)}/bbl`;return state.lang==='pl'?`${main}<small>${fmt(p)} zł/bbl</small>`:main}const main=`$${fmt(u,u<1?6:digits)}`;return state.lang==='pl'?`${main}<small>${fmt(p,p<1?6:digits)} zł</small>`:main}
function valuePrice(pln){const main=state.usdPln?`$${fmt(pln/state.usdPln)}`:'$—';return state.lang==='pl'?`${main}<small>${fmt(pln)} zł</small>`:main}
