function positionBuyUsd(row){const stored=Number(row.buyPriceUsd);if(Number.isFinite(stored)&&stored>=0)return stored;const legacy=Number(row.buyPrice)||0;return state.usdPln?legacy/state.usdPln:legacy}
async function json(url,attempts=2){
  let lastError;
  for(let attempt=0;attempt<attempts;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
    try{const response=await fetch(url,{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error(`${response.status} ${url}`);return await response.json()}
    catch(error){lastError=error;if(attempt+1<attempts)await new Promise(resolve=>setTimeout(resolve,300*(attempt+1)))}
    finally{clearTimeout(timer)}
  }
  throw lastError;
}
function applyBitcoinQuote(usdPrice,change){const price=Number(usdPrice);if(!Number.isFinite(price)||price<=0)return false;state.pricesUSD.btc=price;if(state.usdPln)state.prices.btc=price*state.usdPln;if(Number.isFinite(Number(change)))state.changes.btc=Number(change);localStorage.setItem('vestorBtcQuote',JSON.stringify({price,change:Number.isFinite(Number(change))?Number(change):state.changes.btc,at:Date.now()}));return true}
function restoreBitcoinQuote(){try{const cached=JSON.parse(localStorage.getItem('vestorBtcQuote')||'null');if(cached&&Date.now()-Number(cached.at)<86400000)applyBitcoinQuote(cached.price,cached.change)}catch{}}
function restoreQuoteCache(){
  try{const cache=JSON.parse(localStorage.getItem('vestorQuoteCache')||'null');if(!cache)return false;Object.assign(state.prices,cache.prices||{});Object.assign(state.pricesUSD,cache.pricesUSD||{});Object.assign(state.changes,cache.changes||{});Object.assign(state.marketSparkPoints,cache.marketSparkPoints||{});if(!state.usdPln&&Number(cache.usdPln)>0)state.usdPln=Number(cache.usdPln);return true}catch{return false}
}
