function getPublicWallets(){try{const rows=JSON.parse(sessionStorage.getItem(publicWalletsKey())||'[]');if(Array.isArray(rows)&&rows.length)return rows;const seen=new Map;getPortfolio().filter(row=>row.walletImported&&row.walletId).forEach(row=>seen.set(row.walletId,{id:row.walletId,network:row.walletNetwork,address:row.walletAddress,lastSync:new Date(row.added||row.purchasedAt).getTime()}));return [...seen.values()]}catch{return []}}
function savePublicWallets(rows){sessionStorage.setItem(publicWalletsKey(),JSON.stringify(rows));renderConnectedWallets()}
function shortAddress(address){return `${address.slice(0,8)}…${address.slice(-6)}`}
function renderConnectedWallets(){const target=$('#connectedWallets');if(!target||!state.user)return;const rows=getPublicWallets();target.innerHTML=rows.map(wallet=>{const network=safeText(wallet.network),address=safeText(wallet.address),id=safeText(wallet.id),networkName=safeText(walletNetworks[wallet.network]?.name||wallet.network),symbol=safeText(wallet.network==='bitcoin'?'₿':walletNetworks[wallet.network]?.symbol?.slice(0,2)||'◇');return `<article><span class="wallet-network">${symbol}</span><div><b>${networkName}</b><code title="${address}">${safeText(shortAddress(String(wallet.address||'')))}</code><small>${wallet.lastSync?new Intl.DateTimeFormat(state.lang==='pl'?'pl-PL':'en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(wallet.lastSync)):'—'}</small></div><button data-wallet-sync="${id}" data-wallet-network="${network}">${t('walletSync')}</button><button class="remove" data-wallet-remove="${id}">${t('walletRemove')}</button></article>`}).join('');$$('[data-wallet-sync]').forEach(button=>button.addEventListener('click',()=>{const wallet=getPublicWallets().find(row=>row.id===button.dataset.walletSync);if(wallet)syncPublicWallet(wallet.network,wallet.address)}));$$('[data-wallet-remove]').forEach(button=>button.addEventListener('click',()=>removePublicWallet(button.dataset.walletRemove)))}
