async function fetchText(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error(String(response.status));return await response.text()}finally{clearTimeout(timer)}}
async function readBitcoinWallet(address){const satoshi=Number(await fetchText(`https://blockchain.info/q/addressbalance/${encodeURIComponent(address)}?cors=true`));if(!Number.isFinite(satoshi))throw Error('balance');return satoshi>0?[{asset:'btc',quantity:satoshi/1e8,price:assetUsd('btc'),meta:null}]:[]}
async function readBlockscoutWallet(network,address){const config=walletNetworks[network],base=`${config.explorer}/addresses/${encodeURIComponent(address)}`,[account,tokens]=await Promise.all([json(base),json(`${base}/token-balances`)]),balances=[],nativeBalance=Number(account.coin_balance)/1e18||0,nativePrice=Number(account.exchange_rate)||0,nativeAsset=walletAsset(config.symbol,config.name,'native',nativePrice,network);if(nativeBalance>0)balances.push({asset:nativeAsset.id,quantity:nativeBalance,price:nativePrice||assetUsd(nativeAsset.id),meta:nativeAsset.meta});for(const row of (Array.isArray(tokens)?tokens:[]).slice(0,150)){const info=row.token||{};if(info.type&&info.type!=='ERC-20')continue;const decimals=Math.max(0,Math.min(30,Number(info.decimals)||0)),quantity=Number(row.value)/10**decimals;if(!Number.isFinite(quantity)||quantity<=0||!info.symbol)continue;const price=Number(info.exchange_rate)||0,item=walletAsset(info.symbol,info.name,info.address_hash,price,network);balances.push({asset:item.id,quantity,price:price||assetUsd(item.id),meta:item.meta})}return balances}
async function rpcCall(url,method,params){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:controller.signal});if(!response.ok)throw Error(String(response.status));const data=await response.json();if(data.error)throw Error(data.error.message);return data.result}finally{clearTimeout(timer)}}
