async function syncPublicWallet(network,address){const status=$('#walletImportStatus'),button=$('#walletImportButton');status.className='wallet-import-status loading';status.textContent=t('walletLoading');button?.classList.add('spin');try{const isEvm=/^0x[a-fA-F0-9]{40}$/.test(address),isBtc=/^(bc1|[13])[a-zA-HJ-NP-Z0-9]{20,70}$/.test(address),isTron=/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(address);if((network==='bitcoin'&&!isBtc)||(network==='tron'&&!isTron)||(!['bitcoin','tron'].includes(network)&&!isEvm)||!walletNetworks[network])throw Error('invalid');const config=walletNetworks[network],balances=network==='bitcoin'?await readBitcoinWallet(address):network==='tron'?await readTronWallet(address):config.explorer?await readBlockscoutWallet(network,address):await readRpcStableWallet(network,address);if(!balances.length)throw Error('empty');const walletId=`${network}:${address.toLowerCase()}`,existing=getPortfolio(),previous=new Map(existing.filter(row=>row.walletId===walletId).map(row=>[row.asset,row])),preserved=existing.filter(row=>row.walletId!==walletId),now=new Date().toISOString(),imported=balances.map(item=>{const old=previous.get(item.asset),price=Number(item.price)||0,buyPriceUsd=old?positionBuyUsd(old):price;return {asset:item.asset,quantity:item.quantity,buyPriceUsd,buyPrice:state.usdPln?buyPriceUsd*state.usdPln:buyPriceUsd,purchasedAt:old?.purchasedAt||now,added:old?.added||now,storageLabel:old?.storageLabel||walletNetworks[network]?.name||'',walletImported:true,walletId,walletNetwork:network,walletAddress:address,assetMeta:item.meta||old?.assetMeta||null}});savePortfolio([...preserved,...imported]);const wallets=getPublicWallets().filter(row=>row.id!==walletId);wallets.push({id:walletId,network,address,lastSync:Date.now()});savePublicWallets(wallets);status.className='wallet-import-status success';status.textContent=`${t('walletImported')}: ${balances.length} ${state.lang==='pl'?'aktywów':'assets'}`;renderPortfolio()}catch(error){status.className='wallet-import-status error';status.textContent=error.message==='invalid'?t('walletInvalid'):error.message==='empty'?t('walletEmpty'):t('walletError')}finally{button?.classList.remove('spin')}}
function removePublicWallet(walletId){savePublicWallets(getPublicWallets().filter(row=>row.id!==walletId));savePortfolio(getPortfolio().filter(row=>row.walletId!==walletId));renderPortfolio();$('#walletImportStatus').textContent=''}
async function autoSyncPublicWallets(){const wallets=getPublicWallets().filter(wallet=>!wallet.lastSync||Date.now()-wallet.lastSync>300000);for(const wallet of wallets)await syncPublicWallet(wallet.network,wallet.address)}
$('#walletImportForm').addEventListener('submit',event=>{event.preventDefault();syncPublicWallet($('#walletNetwork').value,$('#walletAddress').value.trim())});

