  const price=numbers.find(value=>value>1&&value<15)??null,changeMatch=block.match(/([▲▼])\s*([+-]?[0-9]+[.,][0-9]+)/),change=changeMatch?(changeMatch[1]==='▼'?-1:1)*Math.abs(Number(changeMatch[2].replace(',','.'))):null;
