  const prices={gasoline:read(/Benzyna\s*Pb95\s+([0-9]+[.,][0-9]+)/i),gasoline_premium:read(/Benzyna\s*Pb98\s+([0-9]+[.,][0-9]+)/i),diesel:read(/Olej\s+Napędowy[\s\S]{0,30}?([0-9]+[.,][0-9]+)/i),diesel_premium:null,lpg:read(/Auto-?Gaz\s+LPG\s+([0-9]+[.,][0-9]+)/i)};
