  return {currency:'PLN',unit:'liter',fetched_at:new Date().toISOString(),station_reports:true,prices,price_changes,price_changes_30d,sources:['PaliwoMapa.pl'],source_url:'https://paliwomapa.pl/historia-cen/'};
