    const response=await fetch('https://r.jina.ai/https://monitorcenpaliw.pl/',{cache:'no-store'});if(!response.ok)throw primaryError;
    const prices=parseMonitorFuelPrices(await response.text()),weeklyText=await weeklyRequest,weeklyData=parsePolishFuelSources(weeklyText,weeklyText);
    return {...weeklyData,prices,price_changes_30d:{},fetched_at:new Date().toISOString(),sources:['Monitor Cen Paliw','PaliwoMapa.pl'],source_url:'https://monitorcenpaliw.pl/'};
