  const {prices={},price_changes:changes={},currency,unit,fetched_at:snapshot,sources=[]}=selected,tiles=[['95',prices.gasoline,changes.gasoline],['98',prices.gasoline_premium??prices.premium,changes.gasoline_premium],['ON',prices.diesel,changes.diesel],['ON+',prices.diesel_premium,changes.diesel_premium],['LPG',prices.lpg,changes.lpg]];
