async function loadFuelPrices(force=false){
  if(fuelLoading)return fuelLoading;
  const cacheKey='vestorFuelPricesV3',cached=(()=>{try{return JSON.parse(localStorage.getItem(cacheKey)||'null')}catch{return null}})();
  if(!force&&cached?.data&&Date.now()-Number(cached.at)<21600000){fuelPrices=cached.data;fuelRates=cached.rates||fuelRates;renderFuelPrices();return}
  fuelLoading=(async()=>{try{
    const [europeResult,fxResult,polandResult]=await Promise.allSettled([json('https://openvan.camp/api/fuel/prices?source=vestor'),json('https://openvan.camp/api/currency/rates'),loadPolishFuelPrices()]);
    fuelPrices={...(cached?.data||{}),...(europeResult.status==='fulfilled'?(europeResult.value.data||{}):{})};
    if(polandResult.status==='fulfilled')fuelPrices.PL=polandResult.value;
    else if(!fuelPrices.PL)throw polandResult.reason||Error('Polish fuel data unavailable');
    if(fxResult.status==='fulfilled')fuelRates={...fuelRates,...fxResult.value.rates};
    else if(cached?.rates)fuelRates={...fuelRates,...cached.rates};
    const at=Date.now(),history=fuelHistory().filter(row=>at-Number(row.at)<65*86400000&&Math.abs(at-Number(row.at))>5*86400000);history.push({at,data:fuelPrices});localStorage.setItem('vestorFuelHistoryV1',JSON.stringify(history));localStorage.setItem(cacheKey,JSON.stringify({at,data:fuelPrices,rates:fuelRates}));renderFuelPrices()
  }catch(error){if(cached?.data){fuelPrices=cached.data;fuelRates=cached.rates||fuelRates;renderFuelPrices()}else{$('#fuelPriceGrid').innerHTML=`<div class="table-loading">${state.lang==='pl'?'Nie udało się pobrać cen. Kliknij Odśwież.':'Could not load prices. Click Refresh.'}</div>`}console.warn('Fuel prices unavailable',error)}finally{fuelLoading=null}})();
  return fuelLoading;
}
