function drawCoinChart(points){if(points.length<2)return;const sampled=points.filter((_,i)=>i%Math.max(1,Math.floor(points.length/180))===0),values=sampled.map(p=>p[1]),lo=Math.min(...values),hi=Math.max(...values),w=900,h=330,pad=20,path=sampled.map((p,i)=>`${i?'L':'M'}${pad+i*(w-pad*2)/(sampled.length-1)},${pad+(hi-p[1])*(h-pad*2)/(hi-lo||1)}`).join(' '),up=values.at(-1)>=values[0];$('#coinChart').innerHTML=`<div class="chart-price-range"><span>$${fmt(hi)}</span><span>$${fmt(lo)}</span></div><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="coinArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${up?'#25d695':'#ff5d72'}" stop-opacity=".28"/><stop offset="1" stop-color="${up?'#25d695':'#ff5d72'}" stop-opacity="0"/></linearGradient></defs><path class="detail-area" d="${path} L${w-pad},${h-pad} L${pad},${h-pad}Z"/><path class="detail-line ${up?'up':'down'}" d="${path}"/></svg>`}
