function calculateRsi(values,period=14){if(values.length<=period)return null;let gains=0,losses=0;for(let i=values.length-period;i<values.length;i++){const diff=values[i]-values[i-1];if(diff>=0)gains+=diff;else losses-=diff}if(!losses)return 100;return 100-(100/(1+gains/losses))}
