function accumulationValue(payload,key){
  const wanted=key.toLowerCase().replace(/[^a-z0-9]/g,''),queue=[payload],seen=new Set();
  while(queue.length){
    const root=queue.shift();if(!root||typeof root!=='object'||seen.has(root))continue;seen.add(root);
    for(const [name,direct] of Object.entries(root)){
      if(name.toLowerCase().replace(/[^a-z0-9]/g,'')===wanted){
        const value=typeof direct==='object'?(direct?.value??direct?.current??direct?.latest):direct;
        if(Number.isFinite(Number(value)))return Number(value);
      }
      if(direct&&typeof direct==='object'&&queue.length<80)queue.push(direct);
    }
  }
  return null;
}
function accumulationSignal(value,bands){
  if(!Number.isFinite(value))return 0;
  for(const [limit,signal] of bands)if(value<=limit)return signal;
  return bands.at(-1)[1];
}
