function sma(values,n){return values.map((_,i)=>{if(i<n-1)return null;const part=values.slice(i-n+1,i+1);return part.reduce((a,b)=>a+b,0)/n})}
function ema(values,n){const k=2/(n+1),out=[];values.forEach((value,i)=>out.push(i?value*k+out[i-1]*(1-k):value));return out}
function bollinger(values,direction){const base=sma(values,20);return values.map((_,i)=>{if(i<19)return null;const part=values.slice(i-19,i+1),mean=base[i],sd=Math.sqrt(part.reduce((sum,value)=>sum+(value-mean)**2,0)/20);return mean+direction*sd*2})}
