  $('#etfFlowChart').innerHTML=`<div class="etf-api-placeholder">${state.lang==='pl'?'Pobieranie historii ETF…':'Loading ETF history…'}</div>`;
  const snapshot=BUILTIN_BTC_ETF_FLOWS,cachedAtStart=JSON.parse(localStorage.getItem(cacheKey)||'null'),cachedPrices=new Map((cachedAtStart?.data||[]).filter(row=>Number(row.price_usd)>0).map(row=>[row.date,Number(row.price_usd)]));
  etfFlowHistory=snapshot.rows.map(row=>({date:row.date,timestamp:Date.parse(row.date),flow_usd:Number(row.flow_usd)||0,price_usd:cachedPrices.get(row.date)||0})).filter(row=>Number.isFinite(row.timestamp)).sort((a,b)=>a.timestamp-b.timestamp);
